<?php if(empty($works))return;view('calls-assets'); ?>
<section class="call-public-works panel"><h2>آثار و روایت‌های فراخوان</h2><?php foreach($works as $work):$files=!empty($onlyAdditional)?array_filter($work['files'],fn($f)=>$f['kind']!=='media'):$work['files'];if(!empty($onlyAdditional)&&!$files&&$work['text']==='')continue; ?><article class="call-public-work"><h3><?= e($work['data']['title']) ?></h3><p class="muted">صاحب اثر: <?php if($work['artist_id']): ?><a href="<?= e(url('artist',['id'=>$work['artist_id']])) ?>"><?= e($work['data']['credit_name']) ?></a><?php else: ?><?= e($work['data']['credit_name']) ?><?php endif ?> · کد <span dir="ltr"><?= e($work['data']['tracking']) ?></span></p><?php if($work['text']!==''): ?><div class="prose"><?= e($work['text']) ?></div><?php endif ?><?php if($work['data']['description']!==''): ?><p class="prose"><?= e($work['data']['description']) ?></p><?php endif ?><div class="call-public-files"><?php foreach($files as $file): ?><?php if($file['image_id']): ?><a href="<?= e(url('image',['id'=>$file['image_id']])) ?>"><img loading="lazy" src="<?= e(url('media',['id'=>$file['image_id']])) ?>" alt="<?= e($work['data']['title']) ?>"><span>مشاهده و دریافت تصویر</span></a><?php else: ?><a class="outline" href="<?= e(url('call-public-file',['id'=>$file['publication_id']])) ?>">دریافت <?= e($file['filename']) ?></a><?php endif ?><?php endforeach ?></div><?php if($work['call_id']): ?><a class="hint" href="<?= e(url('call',['id'=>$work['call_id']])) ?>">فراخوان <?= e($work['call_title']) ?></a><?php endif ?></article><?php endforeach ?></section>